; ==================================================================
; BASICENEMY - MSX GAME ROM
; Generated by Mideas MSX Generator
; Sprites: 1, Tiles: 1
; ==================================================================

    ORG #4000           ; MSX cartridge start address

; ==================================================================
; CARTRIDGE HEADER
; ==================================================================
    DB "AB"             ; MSX cartridge signature
    DW INIT_ROM         ; Initialization address
    DW 0                ; Statement handler (not used)
    DW 0                ; Device handler (not used)
    DW 0                ; Text handler (not used)
    DW 0                ; Reserved
    DW 0                ; Reserved
    DW 0                ; Reserved

; ==================================================================
; MSX BIOS FUNCTIONS
; ==================================================================
CHGMOD  EQU #005F        ; Change screen mode
CLS     EQU #00C3        ; Clear screen
LDIRVM  EQU #005C        ; Block transfer to VRAM
WRTVRM  EQU #004D        ; Write to VRAM
RDVRM   EQU #004A        ; Read from VRAM
WRTVDP  EQU #0047        ; Write to VDP register
GTSTCK  EQU #00D5        ; Get joystick status

; ==================================================================
; VDP PORTS AND ADDRESSES
; ==================================================================
VDPDR   EQU #0098        ; VDP Data Register
VDPSR   EQU #0099        ; VDP Status Register

; VRAM Layout for Screen 2
CHRTBL  EQU #0000        ; Pattern Generator Table
CLRTBL  EQU #2000        ; Color Table
NAMETBL EQU #1800        ; Name Table
SPRATR  EQU #1B00        ; Sprite Attribute Table
SPRPAT  EQU #3800        ; Sprite Pattern Table

; ==================================================================
; MSX COLORS
; ==================================================================
TRANSPARENT EQU 0
BLACK       EQU 1
MEDIUM_GREEN EQU 2
LIGHT_GREEN EQU 3
DARK_BLUE   EQU 4
LIGHT_BLUE  EQU 5
DARK_RED    EQU 6
CYAN        EQU 7
MEDIUM_RED  EQU 8
LIGHT_RED   EQU 9
DARK_YELLOW EQU 10
LIGHT_YELLOW EQU 11
DARK_GREEN  EQU 12
MAGENTA     EQU 13
GRAY        EQU 14
WHITE       EQU 15

; ==================================================================
; ROM INITIALIZATION
; ==================================================================
INIT_ROM:
    DI                   ; Disable interrupts

    ; Set Screen 2 mode
    LD A, 2
    CALL CHGMOD

    ; Configure VDP for 16x16 sprites
    LD A, %11100010  ; R1: 16K VRAM, Display on, Interrupt on, Sprites 16x16, MAG off
    LD B, 1
    CALL WRTVDP

    ; Clear screen
    CALL CLS

    ; Load sprite patterns
    CALL LOAD_SPRITE_PATTERNS

    ; Load tile patterns
    CALL LOAD_TILE_PATTERNS

    ; Load tile colors
    CALL LOAD_TILE_COLORS

    ; Setup a test screen
    CALL SETUP_TEST_SCREEN

    ; Setup test sprites
    CALL SETUP_TEST_SPRITES

    ; Enable interrupts
    EI

    ; Main loop
MAIN_LOOP:
    HALT                 ; Wait for V-Blank
    JP MAIN_LOOP

; ==================================================================
; SPRITE DATA
; ==================================================================

; Sprite 0: bot1
SPRITE_BOT1_PATTERNS:
    ; Pattern 0
    DB #1F, #7F, #CF, #8F, #07, #00, #2F, #6F
    ; Pattern 1
    DB #E0, #B0, #B0, #F0, #E0, #00, #F0, #BD
    ; Pattern 2
    DB #6F, #6F, #00, #0C, #FC, #FC, #C0, #C0
    ; Pattern 3
    DB #BD, #F0, #00, #1C, #1C, #07, #07, #07

; ==================================================================
; TILE PATTERN DATA
; ==================================================================

; Tile 0: brick1
TILE_BRICK1_PATTERNS:
    ; Pattern 0
    DB #00, #7F, #7F, #7F, #00, #FB, #FB, #FB
    ; Pattern 1
    DB #00, #BF, #BF, #BF, #00, #FD, #FD, #FD
    ; Pattern 2
    DB #00, #7F, #7F, #7F, #00, #FB, #FB, #FB
    ; Pattern 3
    DB #00, #BF, #BF, #BF, #00, #FD, #FD, #FD

; ==================================================================
; TILE COLOR DATA
; ==================================================================

; Tile 0: brick1 colors
TILE_BRICK1_COLORS:
    DB #61, #61, #61, #61, #61, #61, #61, #91, #61, #B1, #61, #61, #61, #61, #61, #61, #61, #61, #61, #61, #61, #61, #61, #61, #61, #61, #B1, #B1, #61, #61, #61, #61

; ==================================================================
; LOADING FUNCTIONS
; ==================================================================

LOAD_SPRITE_PATTERNS:
    ; Load sprite patterns to VRAM
    ; Load sprite 0: bot1
    LD HL, SPRITE_BOT1_PATTERNS
    LD DE, SPRPAT + (0 * 32)
    LD BC, 32
    CALL LDIRVM

    RET

LOAD_TILE_PATTERNS:
    ; Load tile patterns to VRAM
    ; Load tile 0: brick1
    LD HL, TILE_BRICK1_PATTERNS
    LD DE, CHRTBL + (1 * 32)
    LD BC, 32
    CALL LDIRVM

    RET

LOAD_TILE_COLORS:
    ; Load tile colors to VRAM
    ; Load tile 0: brick1 colors
    LD HL, TILE_BRICK1_COLORS
    LD DE, CLRTBL + (1 * 32)
    LD BC, 32
    CALL LDIRVM

    RET

SETUP_TEST_SCREEN:
    ; Setup a test screen with tiles
    LD HL, NAMETBL
    LD DE, NAMETBL + 1
    LD BC, 767           ; Clear name table
    LD (HL), 0
    LDIR

    ; Put some tiles on screen
    LD A, 1              ; Tile pattern 1 (brick)
    LD HL, NAMETBL + (10 * 32) + 10  ; Position 10,10
    CALL WRTVRM

    LD A, 1              ; Another brick
    LD HL, NAMETBL + (10 * 32) + 11  ; Position 11,10
    CALL WRTVRM

    LD A, 1              ; Another brick
    LD HL, NAMETBL + (11 * 32) + 10  ; Position 10,11
    CALL WRTVRM

    LD A, 1              ; Another brick
    LD HL, NAMETBL + (11 * 32) + 11  ; Position 11,11
    CALL WRTVRM

    RET

SETUP_TEST_SPRITES:
    ; Setup test sprites
    ; Clear all sprites first
    LD HL, SPRATR
    LD DE, SPRATR + 1
    LD BC, 127
    LD (HL), #D1         ; Y = 209 (invisible)
    LDIR

    ; Setup sprite 0 (bot1)
    LD A, 100            ; Y position
    LD HL, SPRATR + 0
    CALL WRTVRM

    LD A, 100            ; X position
    LD HL, SPRATR + 1
    CALL WRTVRM

    LD A, 0              ; Pattern 0
    LD HL, SPRATR + 2
    CALL WRTVRM

    LD A, 15             ; Color white
    LD HL, SPRATR + 3
    CALL WRTVRM

    RET

    END                  ; End of assembly
